(function(E){ const x = E["hr-m2"] = E["hr-m2"] || {units:{}}; x.units["hr-2-2"] = {"explain":{"id":"c-hr-2-2-e","course":"hr","unit":"hr-2-2","type":"explain","level":"B1","title":{"en":"Job ads that attract","tr":"Çekici iş ilanları","fa":"آگهی استخدامی که متقاضی جذب می‌کند"},"objective":{"en":"After this lesson, you can write a job ad that speaks to the reader and welcomes every good applicant.","tr":"Bu dersin sonunda okuyana doğrudan seslenen ve her iyi adayı davet eden bir iş ilanı yazabileceksin.","fa":"بعد از این درس می‌توانی آگهی استخدامی بنویسی که با خواننده حرف می‌زند و هر متقاضی خوبی را دعوت می‌کند."},"hook":{"en":"Describe the job, not the person. One careless word can stop a good person applying. Leyla's first ad spoke about the company. Her second one speaks to the reader, and more people apply.","tr":"Kişiyi değil, işi anlat. Dikkatsiz bir kelime iyi bir adayın başvurmasını engelleyebilir. Leyla'nın ilk ilanı şirketten bahsediyordu. İkincisi okura sesleniyor ve daha çok kişi başvuruyor.","fa":"کار را توصیف کن، نه آدم را. یک کلمه‌ی نسنجیده ممکن است متقاضی خوب را از درخواست دادن منصرف کند. آگهی اول لیلا درباره‌ی شرکت حرف می‌زد. آگهی دوم با خواننده حرف می‌زند و آدم‌های بیشتری درخواست می‌دهند."},"before":{"en":"Write the opening lines of a job ad that welcomes everyone and says what the person will do.","tr":"Herkesi davet eden ve kişinin ne yapacağını söyleyen bir iş ilanının ilk satırlarını yaz.","fa":"سطرهای اول یک آگهی شغلی را بنویس که همه را دعوت کند و بگوید آن شخص چه کاری انجام می‌دهد."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"5"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Describe the job, not the person","tr":"Kişiyi değil, işi anlat","fa":"کار را توصیف کن، نه آدم را"},"body":{"en":"Words about age or gender send good people away. So write what the person will actually do.","tr":"Yaş ya da cinsiyetle ilgili kelimeler iyi adayları uzaklaştırır. Bu yüzden kişinin gerçekte ne yapacağını yaz.","fa":"کلمه‌هایی درباره‌ی سن یا جنسیت آدم‌های خوب را دور می‌کنند. پس بنویس آن شخص واقعاً چه کار خواهد کرد."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Speaking to the reader: you, imperatives, who","tr":"Okuyana seslenmek: you, emir kipi, who","fa":"حرف زدن با خواننده: you، فعل امر، who"},"steps":[{"en":"Talk to the reader: you + short imperatives.","tr":"Okura seslen: you + kısa emir cümleleri.","fa":"با خواننده حرف بزن: you و فعل‌های امری کوتاه.","ex":"Join our team. Help us deliver on time."},{"en":"Two instructions joined by and: both verbs stay bare.","tr":"and ile bağlanan iki emir: iki fiil de yalın kalır.","fa":"اگر دو دستور با and وصل شوند، هر دو فعل به شکل ساده می‌مانند.","ex":"Join us and be part of something new."},{"en":"Describe people with who.","tr":"İnsanları who ile tanımla.","fa":"آدم‌ها را با who توصیف کن.","ex":"drivers who enjoy night work"},{"en":"Say what the person does, not who they are.","tr":"Kişinin kim olduğunu değil, ne yaptığını söyle.","fa":"بگو آن فرد چه کاری می‌کند، نه اینکه چه جور آدمی است.","ex":"You will lift boxes up to 20 kg."}],"table":{"headers":{"en":["Instead of","Write"],"tr":["Yerine","Yaz"],"fa":["به‌جای","بنویس"]},"rows":[["young and energetic","You will work at a fast pace."],["native English speaker","Fluent English (spoken and written)."],["He will manage...","You will manage..."],["salesman","sales representative"]]},"tip":{"en":"Turkish and Persian ads often use formal third person ('adaylar...', 'motaqazian...'). English ads speak directly to 'you', which feels warmer, not rude.","tr":"Türkçe ilanlar çoğu zaman resmî üçüncü şahısla yazılır: 'Adayların ... olması gerekir.' İngilizce ilanlar okura doğrudan 'you' diye seslenir; bu kaba değil, sıcak bir tondur.","fa":"آگهی‌های فارسی معمولاً سوم‌شخص و رسمی‌اند: «متقاضیان باید ...». آگهی انگلیسی مستقیم با «you» حرف می‌زند؛ این بی‌ادبی نیست، گرم‌تر است."},"wrong":"Applicants are requested to submit their CVs.","right":"Send us your CV by 30 May."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"It may exclude some good applicants.","meaning":{"en":"Gives a reason without blaming.","tr":"Suçlamadan sebep verir.","fa":"دلیل می‌آورد، بدون اینکه کسی را مقصر کند."}},{"phrase":"What if we say it like this?","meaning":{"en":"Offers an alternative politely.","tr":"Kibarca alternatif sunar.","fa":"مؤدبانه یک راه دیگر پیشنهاد می‌کند."}},{"phrase":"It gives us a bigger pool of candidates.","meaning":{"en":"Shows the business benefit.","tr":"İş yararını gösterir.","fa":"سودش را برای کسب‌وکار نشان می‌دهد."}},{"phrase":"apply","meaning":{"en":"To formally ask for a job.","tr":"başvurmak.","fa":"درخواست دادن (برای یک شغل)"}},{"phrase":"bias","meaning":{"en":"An unfair preference for or against a group.","tr":"önyargı.","fa":"سوگیری؛ پیش‌داوری له یا علیه یک گروه"}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Fair wording is also the law","tr":"Adil dil aynı zamanda yasal bir zorunluluktur","fa":"زبان منصفانه الزام قانونی هم هست"},"body":{"en":"In the UK and the EU, age and gender wording in job ads can break equality law, and UAE law bans hiring discrimination on grounds such as sex, religion and national origin. Inclusive wording also brings more good applicants. EU pay rules (due by June 2026, late in many countries) require the pay range before the interview and ban questions about past pay. Check local law for real ads.","tr":"Birleşik Krallık’ta ve AB’de iş ilanlarındaki yaş ve cinsiyet ifadeleri eşitlik yasasını çiğneyebilir; BAE yasası da işe alımda cinsiyet, din ve ulusal köken gibi nedenlerle ayrımcılığı yasaklar. Kapsayıcı ifade ayrıca daha çok iyi aday getirir. AB maaş kuralları (Haziran 2026’ya kadar yasalaşmalıydı, birçok ülke gecikti) mülakattan önce maaş aralığının söylenmesini ister ve geçmiş maaşı sormayı yasaklar. Gerçek ilanlar için yerel yasayı kontrol et.","fa":"در بریتانیا و اتحادیه‌ی اروپا عبارت‌های مربوط به سن و جنسیت در آگهی استخدام ممکن است قانون برابری را نقض کند، و قانون امارات هم تبعیض در استخدام به دلیل جنسیت، دین یا ملیت را ممنوع کرده است. آگهی فراگیر متقاضیان خوب بیشتری هم می‌آورد. قوانین شفافیت حقوق در اتحادیه‌ی اروپا (که باید تا ژوئن ۲۰۲۶ وارد قانون کشورها می‌شد و خیلی از کشورها عقب‌اند) می‌گوید بازه‌ی حقوق باید قبل از مصاحبه گفته شود و پرسیدن حقوق قبلی ممنوع است. برای آگهی واقعی قانون محلی را بررسی کن."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از توصیف آدم تا توصیف کار"},"text":"Facts: The job: answering calls and planning the team's diary.","item":"We want a dynamic young man for our busy office.","why":{"en":"Weak: it describes a type of person. Strong: it describes the work.","tr":"Zayıf: bir insan tipini anlatıyor. Güçlü: işi anlatıyor.","fa":"نسخه‌ی اول یک تیپ آدم را توصیف می‌کند. نسخه‌ی دوم خود کار را توصیف می‌کند."},"answer":"You will answer calls and plan the team's diary.","cut":["dynamic","young man"],"cutHint":{"en":"Tap the words that send good people away.","tr":"İyi adayları uzaklaştıran kelimelere dokun.","fa":"روی کلمه‌هایی بزن که آدم‌های خوب را فراری می‌دهند."}},"quick":{"prompt":"Why take \"young\" out of a job ad in the UK or the EU?","options":["Age wording can break equality law","It makes the ad shorter","Young people do not read ads"],"correct":0,"why":{"en":"Age wording can break equality law, and inclusive wording also brings more good applicants.","tr":"Yaşla ilgili ifadeler eşitlik yasalarını çiğneyebilir; kapsayıcı ifadeler ayrıca daha çok iyi başvuru getirir.","fa":"عبارت‌های مربوط به سن می‌توانند قانون برابری را نقض کنند و زبانِ فراگیر متقاضیان خوبِ بیشتری هم می‌آورد."},"point":4,"hint2":{"en":"Think about the law on fair hiring. What can age wording in an ad lead to?","tr":"Adil işe alımla ilgili yasaları düşün. İlandaki yaşla ilgili ifadeler neye yol açabilir?","fa":"به قانون استخدام منصفانه فکر کن. عبارت‌های مربوط به سن در آگهی می‌توانند به چه چیزی منجر شوند؟"}},"remember":{"en":"Read the ad as someone aged 52, or as a mother of two. Does any word tell you not to apply? Change it. Result of this lesson: you can write a welcoming job ad. You also have one.","tr":"İlanı 52 yaşında biri ya da iki çocuk annesi gibi oku. Bir kelime sana 'başvurma' diyor mu? Onu değiştir. Bu dersin sonucu: herkese açık, davetkâr bir iş ilanı yazabilirsin ve elinde hazır bir ilan olur.","fa":"آگهی را از نگاه یک آدم ۵۲ ساله یا یک مادر با دو بچه بخوان. کلمه‌ای هست که بگوید «درخواست نده»؟ عوضش کن. حالا می‌توانی آگهی استخدامی بنویسی که همه را به درخواست دادن دعوت کند. یک آگهی آماده هم داری."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Inclusive grammar: singular they, whether... or...","tr":"Kapsayıcı dil bilgisi: tekil they, whether... or...","fa":"زبان فراگیر: they مفرد، whether... or..."},"steps":[{"en":"One person, gender unknown: they, them, their.","tr":"Tek kişi, cinsiyeti bilinmiyor: they, them, their.","fa":"برای کسی که جنسیتش را نمی‌دانی، they، them و their را به کار ببر.","ex":"If a candidate needs an adjustment, they can tell us."},{"en":"The verb with singular they stays plural.","tr":"Tekil they ile fiil yine çoğul kalır.","fa":"فعلِ they مفرد هم جمع می‌ماند.","ex":"they are, not they is"},{"en":"Welcome two groups: whether... or...","tr":"İki grubu karşıla: whether... or...","fa":"برای خوشامد به دو گروه، whether... or... را به کار ببر.","ex":"Whether you are starting out or returning to work, ..."}],"table":{"headers":{"en":["Tool","Example"],"tr":["Araç","Örnek"],"fa":["ابزار","مثال"]},"rows":[["Singular they","If a candidate needs an adjustment, they can tell us."],["their / them","Each driver receives their schedule two weeks ahead."],["whether... or...","Whether you are starting out or returning to work, apply today."]]},"body":{"en":"B2 track: your ad must include one whether... or... sentence and refer to the applicant with they or their at least once.","tr":"B2 yolu: ilanında bir whether... or... cümlesi olmalı ve adaydan en az bir kez they veya their ile bahsetmelisin.","fa":"مسیر B2: آگهی تو باید یک جمله با whether... or... داشته باشد و دست‌کم یک بار با they یا their به متقاضی اشاره کند."}},"source":{"en":"Based on Acas guidance on job ads and the EU Pay Transparency Directive.","tr":"Acas’ın iş ilanı rehberine ve AB Ücret Şeffaflığı Direktifi’ne dayanır.","fa":"بر پایه‌ی راهنمای Acas درباره‌ی آگهی استخدام و دستورالعمل شفافیت حقوق اتحادیه‌ی اروپا."}},"grammar":{"id":"c-hr-2-2-g","level":"B1","course":"hr","unit":"hr-2-2","title":"Speaking to the reader: you, imperatives, who","titleTr":"Okuyana seslenmek: you, emir kipi, who","exp":{"en":"A job ad is a short sales text, so it speaks to the reader. Use \"you\" and short imperatives: \"Join our team.\", \"Help us deliver on time.\" After an imperative the verb is the base form: \"Join us and be part of something new.\" (not \"and being\"). To describe people, use \"who\": \"We are looking for drivers who enjoy night work.\" (not \"what\" or \"whose\"). Also choose words that do not point to age, gender or origin. Write \"energetic\" only if the job is physical, and say what the person does instead of who they are: \"You will lift boxes up to 20 kg\" is better than \"strong young men\".","tr":"İş ilanı kısa bir satış metnidir, bu yüzden okuyana seslenir. \"You\" ve kısa emir kipi kullan: \"Join our team.\", \"Help us deliver on time.\" Emir kipinden sonra fiil yalın hâldedir: \"Join us and be part of something new.\" (\"and being\" değil). İnsanları tanımlamak için \"who\" kullan: \"We are looking for drivers who enjoy night work.\" (\"what\" ya da \"whose\" değil). Ayrıca yaş, cinsiyet veya kökene işaret etmeyen sözcükler seç. \"Energetic\" sadece iş fiziksel ise yaz ve kişinin ne olduğu yerine ne yapacağını söyle: \"You will lift boxes up to 20 kg\" ifadesi \"strong young men\" ifadesinden iyidir.","fa":"آگهی استخدام در واقع یک متن تبلیغاتی کوتاه است، پس مستقیم با خواننده حرف می‌زند. از you و جمله‌های امری کوتاه استفاده کن: «⁨Join our team.⁩» و «⁨Help us deliver on time.⁩» بعد از فعل امر، فعل بعدی هم به شکل ساده می‌آید: «⁨Join us and be part of something new.⁩» (نه «and being»). برای توصیف آدم‌ها از who استفاده کن: «⁨We are looking for drivers who enjoy night work.⁩» (نه what و نه whose). در ضمن، کلمه‌هایی انتخاب کن که به سن، جنسیت یا ملیت اشاره نکنند. energetic را فقط وقتی بنویس که کار واقعاً بدنی است، و به‌جای اینکه بگویی فرد «چه جور آدمی» باشد، بگو «چه کاری» انجام می‌دهد: «You will lift boxes up to 20 kg» خیلی بهتر از «strong young men» است."},"formsTable":{"headers":{"en":["Instead of","Write"],"tr":["Yerine","Yaz"],"fa":["به‌جای","بنویس"]},"rows":[["young and energetic","You will work at a fast pace."],["native English speaker","Fluent English (spoken and written)."],["He will manage...","You will manage..."],["salesman","sales representative"]]},"wrong":"Join us and being part of something new.","right":"Join us and be part of something new.","blank":{"sentence":"Join our team and ___ part of the Dubai story.","word":"be","distractors":["to be","being"]},"wrong2":"We are looking for drivers what enjoy night work.","right2":"We are looking for drivers who enjoy night work.","blank2":{"sentence":"We are looking for drivers ___ enjoy night work.","word":"who","distractors":["what","whose"]},"expParts":{"hook":{"en":"Leyla's first ad spoke about the company. Her second one speaks to the reader, and more people apply.","tr":"Leyla'nın ilk ilanı şirketten bahsediyordu. İkincisi okura sesleniyor ve daha çok kişi başvuruyor.","fa":"آگهی اول لیلا درباره‌ی شرکت حرف می‌زد. آگهی دوم با خواننده حرف می‌زند و آدم‌های بیشتری درخواست می‌دهند."},"tryWhy":{"en":"who: who describes people. what and whose cannot start this description.","tr":"who: who insanları tanımlar. Bu tanımı what ya da whose başlatamaz.","fa":"جواب who است: برای توصیف آدم‌ها who می‌آید. what و whose نمی‌توانند این توصیف را شروع کنند."},"rule":[{"en":"Talk to the reader: you + short imperatives.","tr":"Okura seslen: you + kısa emir cümleleri.","fa":"با خواننده حرف بزن: you و فعل‌های امری کوتاه.","ex":"Join our team. Help us deliver on time."},{"en":"Imperative + and + another bare verb.","tr":"Emir + and + yine yalın fiil.","fa":"بعد از فعل امری و and هم فعل ساده می‌آید.","ex":"Join us and be part of something new."},{"en":"Describe people with who.","tr":"İnsanları who ile tanımla.","fa":"آدم‌ها را با who توصیف کن.","ex":"drivers who enjoy night work"},{"en":"Say what the person does, not who they are.","tr":"Kişinin kim olduğunu değil, ne yaptığını söyle.","fa":"بگو آن فرد چه کاری می‌کند، نه اینکه چه جور آدمی است.","ex":"You will lift boxes up to 20 kg."}],"test":{"en":"Read the ad as someone aged 52, or as a mother of two. Does any word tell you not to apply? Change it.","tr":"İlanı 52 yaşında biri ya da iki çocuk annesi gibi oku. Bir kelime sana 'başvurma' diyor mu? Onu değiştir.","fa":"آگهی را از نگاه یک آدم ۵۲ ساله یا یک مادر با دو بچه بخوان. کلمه‌ای هست که بگوید «درخواست نده»؟ عوضش کن."},"contrast":{"en":"Turkish and Persian ads often use formal third person ('adaylar...', 'motaqazian...'). English ads speak directly to 'you', which feels warmer, not rude.","tr":"Türkçe ilanlar çoğu zaman resmî üçüncü şahısla yazılır: 'Adayların ... olması gerekir.' İngilizce ilanlar okura doğrudan 'you' diye seslenir; bu kaba değil, sıcak bir tondur.","fa":"آگهی‌های فارسی معمولاً سوم‌شخص و رسمی‌اند: «متقاضیان باید ...». آگهی انگلیسی مستقیم با «you» حرف می‌زند؛ این بی‌ادبی نیست، گرم‌تر است."}},"errorWatch":[{"find":["and being part","and to be part","and joining our"],"fix":{"en":"After an imperative + and, use the bare verb: 'Join us and be part of something new.'","tr":"Emir + and'den sonra yalın fiil kullan: 'Join us and be part of something new.'","fa":"بعد از فعل امری و and، فعل ساده بیاور: «Join us and be part of something new.»"}},{"find":["drivers what","people what","candidates what","applicants what","drivers whose enjoy"],"fix":{"en":"Use who for people: 'drivers who enjoy night work'.","tr":"İnsanlar için who kullan: 'drivers who enjoy night work'.","fa":"برای آدم‌ها who بنویس: «drivers who enjoy night work»."}},{"find":["young and energetic","young, energetic","strong men","young team","native english","native speaker","salesman"],"fix":{"en":"This points to age, gender or origin. Say what the person does instead: 'You will lift boxes up to 20 kg.'","tr":"Bu ifade yaşa, cinsiyete ya da kökene işaret ediyor. Onun yerine kişinin ne yapacağını söyle: 'You will lift boxes up to 20 kg.'","fa":"این عبارت به سن، جنسیت یا ملیت اشاره دارد. به‌جایش بگو آن فرد چه کار می‌کند: «⁨You will lift boxes up to 20 kg.⁩»"}}]},"b2":{"id":"c-hr-2-2-b2","level":"B2","track":"B2","course":"hr","unit":"hr-2-2","title":"Inclusive grammar: singular they, whether... or...","titleTr":"Kapsayıcı dil bilgisi: tekil they, whether... or...","exp":{"en":"Two grammar tools make an ad open to everyone. First, singular they: when you talk about one person whose gender you do not know, modern professional English uses they, them, their: \"If a candidate needs an adjustment, they can tell us at any stage.\" The verb stays plural: \"they are\", even for one person. Second, whether... or... welcomes different groups in one sentence: \"Whether you are starting out or returning to work, we would like to hear from you.\" Do not replace whether with either here (\"Either you are starting out or...\" changes the meaning to a choice of two facts about the reader).","tr":"İki dil bilgisi aracı ilanı herkese açık yapar. Birincisi tekil they: cinsiyetini bilmediğin tek bir kişiden bahsederken modern profesyonel İngilizce they, them, their kullanır: \"If a candidate needs an adjustment, they can tell us at any stage.\" Türkçede \"o\" zaten cinsiyetsizdir; İngilizcede bu işi they görür. Fiil çoğul kalır: tek kişi için bile \"they are\". İkincisi whether... or... farklı grupları tek cümlede karşılar: \"Whether you are starting out or returning to work, we would like to hear from you.\" Burada whether yerine either kullanma (\"Either you are starting out or...\" anlamı okuyucu hakkında iki seçenekten birine çevirir).","fa":"دو ابزار دستوری آگهی را به روی همه باز می‌کند. اول، they مفرد (singular they): وقتی درباره‌ی یک نفر حرف می‌زنی و جنسیتش را نمی‌دانی، انگلیسی حرفه‌ای امروز از they، them و their استفاده می‌کند: «⁨If a candidate needs an adjustment, they can tell us at any stage.⁩» در فارسی «او» خودش بی‌جنسیت است و این مشکل را نداریم؛ در انگلیسی این نقش را they بازی می‌کند. فعلش هم جمع می‌ماند: حتی برای یک نفر می‌گوییم «they are». دوم، ساختار whether... or... که در یک جمله به گروه‌های مختلف خوشامد می‌گوید: «⁨Whether you are starting out or returning to work, we would like to hear from you.⁩» یعنی «چه تازه‌کار باشید، چه بعد از وقفه به کار برگردید». اینجا either را جای whether نگذار؛ «⁨Either you are starting out or...⁩» یعنی «یکی از این دو حالت درباره‌ی شما صدق می‌کند» و معنی کاملاً عوض می‌شود."},"formsTable":{"headers":{"en":["Tool","Example"],"tr":["Araç","Örnek"],"fa":["ابزار","مثال"]},"rows":[["Singular they","If a candidate needs an adjustment, they can tell us."],["their / them","Each driver receives their schedule two weeks ahead."],["whether... or...","Whether you are starting out or returning to work, apply today."]]},"wrong":"If a candidate needs an adjustment, it can tell us at any stage.","right":"If a candidate needs an adjustment, they can tell us at any stage.","blank":{"sentence":"If a candidate needs an adjustment, ___ can tell us at any stage.","word":"they","distractors":["it","them"]},"wrong2":"Either you are starting out or returning to work, we would like to hear from you.","right2":"Whether you are starting out or returning to work, we would like to hear from you.","blank2":{"sentence":"___ you are starting out or returning to work, we would like to hear from you.","word":"Whether","distractors":["Either","Although"]},"useIn":{"en":"B2 track: your ad must include one whether... or... sentence and refer to the applicant with they or their at least once.","tr":"B2 yolu: ilanında bir whether... or... cümlesi olmalı ve adaydan en az bir kez they veya their ile bahsetmelisin.","fa":"مسیر B2: آگهی تو باید یک جمله با whether... or... داشته باشد و دست‌کم یک بار با they یا their به متقاضی اشاره کند."},"exitItem":{"from":"hr-2-2","kind":"blank","prompt":"Every applicant should send ___ CV by Friday.","options":["their","they","them"],"correct":0,"why":{"en":"their: singular 'they' uses their for 'every applicant', so no one is left out. 'They' and 'them' are the wrong forms before CV.","tr":"their: tekil 'they', 'every applicant' için their kullanır; böylece kimse dışarıda kalmaz. CV'den önce 'they' ve 'them' yanlış biçimlerdir.","fa":"their درست است، چون they مفرد برای every applicant صفت ملکی their می‌گیرد تا کسی کنار گذاشته نشود. they و them قبل از CV شکل اشتباه‌اند."}},"expParts":{"hook":{"en":"Two small words open the ad to everyone: they for one person, and whether... or...","tr":"İki küçük kelime ilanı herkese açar: tek kişi için they ve whether... or...","fa":"دو کلمه‌ی کوچک آگهی را به روی همه باز می‌کند: they برای یک نفر و ⁨whether... or...⁩"},"tryWhy":{"en":"Whether: it welcomes two groups in one sentence. Either would make it a choice between two facts.","tr":"Whether: tek cümlede iki grubu birden karşılar. Either kullanırsan iki bilgi arasında bir seçime dönüşür.","fa":"جواب Whether است: در یک جمله به دو گروه خوشامد می‌گوید. اگر either بگذاری، جمله به انتخاب بین دو واقعیت تبدیل می‌شود."},"rule":[{"en":"One person, gender unknown: they, them, their.","tr":"Tek kişi, cinsiyeti bilinmiyor: they, them, their.","fa":"برای کسی که جنسیتش را نمی‌دانی، they، them و their را به کار ببر.","ex":"If a candidate needs an adjustment, they can tell us."},{"en":"The verb with singular they stays plural.","tr":"Tekil they ile fiil yine çoğul kalır.","fa":"فعلِ they مفرد هم جمع می‌ماند.","ex":"they are, not they is"},{"en":"Welcome two groups: whether... or...","tr":"İki grubu karşıla: whether... or...","fa":"برای خوشامد به دو گروه، whether... or... را به کار ببر.","ex":"Whether you are starting out or returning to work, ..."}],"test":{"en":"Writing about one unknown person? Try he, then she. If either one leaves people out, use they.","tr":"Bilinmeyen tek bir kişiden mi bahsediyorsun? Önce he, sonra she dene. İkisi de birilerini dışarıda bırakıyorsa they kullan.","fa":"درباره‌ی یک آدم ناشناس می‌نویسی؟ he و بعد she را امتحان کن. اگر هر کدام عده‌ای را کنار می‌گذارد، they بنویس."},"contrast":{"en":"Turkish o and Persian u have no gender, so this problem does not exist at home. In English, he or she shuts some readers out; they keeps everyone in.","tr":"Türkçedeki 'o' cinsiyetsizdir, bu yüzden bu sorun Türkçede yoktur. İngilizcede he ya da she bazı okurları dışarıda bırakır; they herkesi içeride tutar.","fa":"در فارسی «او» خودش بی‌جنسیت است و این مشکل را نداریم. در انگلیسی he یا she بعضی خواننده‌ها را کنار می‌گذارد؛ they همه را نگه می‌دارد."}},"errorWatch":[{"find":["needs an adjustment, it","needs help, it can","the candidate, it"],"fix":{"en":"For a person, use they, not it: 'If a candidate needs an adjustment, they can tell us.'","tr":"Bir kişi için it değil they kullan: 'If a candidate needs an adjustment, they can tell us.'","fa":"برای آدم they بنویس نه it: «⁨If a candidate needs an adjustment, they can tell us.⁩»"}},{"find":["either you are starting","either you are new","either you have"],"fix":{"en":"To welcome two groups, use whether... or...: 'Whether you are starting out or returning to work, ...'","tr":"İki grubu karşılamak için whether... or... kullan: 'Whether you are starting out or returning to work, ...'","fa":"برای خوشامد به دو گروه بنویس whether... or...: «Whether you are starting out or returning to work, ...»"}}]},"vocab":{"id":"c-hr-2-2-v","level":"B1","category":"vocab","course":"hr","unit":"hr-2-2","goals":["career"],"title":{"en":"Job Ad Language","tr":"İş İlanı Dili","fa":"زبان آگهی استخدام"},"cards":[{"word":"apply","sentence":"Apply by 15 November.","meaning":{"en":"To formally ask for a job.","tr":"başvurmak.","fa":"درخواست دادن (برای یک شغل)"}},{"word":"inclusive","sentence":"We write inclusive ads so everyone feels welcome.","meaning":{"en":"Open to all kinds of people.","tr":"kapsayıcı.","fa":"فراگیر؛ پذیرای همه‌ی افراد"}},{"word":"bias","sentence":"Words like \"young\" show age bias.","meaning":{"en":"An unfair preference for or against a group.","tr":"önyargı.","fa":"سوگیری؛ پیش‌داوری له یا علیه یک گروه"}},{"word":"benefits","sentence":"Benefits include health insurance and a travel allowance.","meaning":{"en":"Extras you get besides your salary.","tr":"yan haklar.","fa":"مزایا (هر چیزی جز حقوق پایه)"}},{"word":"competitive salary","sentence":"'Competitive salary' tells applicants very little; a pay range tells them more.","meaning":{"en":"Pay as good as other companies'. Common in ads, but vague: a range is clearer.","tr":"rekabetçi maaş (ilanlarda sık görülür ama belirsizdir; maaş aralığı daha nettir).","fa":"حقوق رقابتی؛ هم‌سطح بازار (در آگهی‌ها رایج است، اما مبهم؛ بازه‌ی حقوق روشن‌تر است)"}},{"word":"closing date","sentence":"The closing date is 15 November.","meaning":{"en":"The last day you can apply.","tr":"son başvuru tarihi.","fa":"آخرین مهلت ارسال درخواست"}},{"word":"full-time","sentence":"This is a full-time role, 40 hours a week.","meaning":{"en":"Working a normal full week.","tr":"tam zamanlı.","fa":"تمام‌وقت"}},{"word":"flexible","sentence":"We offer flexible working hours.","meaning":{"en":"Able to change when needed.","tr":"esnek.","fa":"منعطف؛ شناور"}},{"word":"gender-neutral","sentence":"Use gender-neutral job titles, such as \"chair\".","meaning":{"en":"Not pointing to men or women.","tr":"cinsiyetten bağımsız.","fa":"بدون اشاره به جنسیت؛ خنثی از نظر جنسیت"}},{"word":"reasonable adjustments","sentence":"We make reasonable adjustments for applicants with disabilities.","meaning":{"en":"Changes that help people with disabilities to work or interview.","tr":"makul düzenlemeler.","fa":"تسهیلات متناسب (تغییراتی که به افراد دارای معلولیت کمک می‌کند کار کنند یا در مصاحبه شرکت کنند)"}}]},"story":{"id":"c-hr-2-2-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-2-2","title":{"en":"Young and Energetic","tr":"Genç ve Enerjik","fa":"جوان و پرانرژی"},"text":"Leyla finished the ad before lunch. She was proud of it. The first line said: \"We are a young, energetic team. We need strong men who can drive at night.\"\n\nSelin read it over her shoulder. \"Leyla. Who can apply to this?\"\n\n\"Drivers,\" Leyla said.\n\n\"Which drivers? Read it again as someone else.\"\n\nLeyla read it as Nermin, 52, a former fleet coordinator who wanted to move into driving and training. Nermin was not young. Nermin was not a man. Nermin would close the page after one line.\n\nShe read it as Ece, 34, a driver with two children. \"Energetic team, night work.\" Nothing about hours. Ece wanted to know if she could plan her week, and the ad did not say.\n\nLeyla felt a little cold. She had not planned to leave anyone out. She had just written the way the old ads sounded.\n\nShe started again. \"Join our growing team in Dubai. We are looking for drivers who enjoy road work and take pride in on-time delivery. You will drive on a fixed route. You will work three or four nights a week, and your schedule will be shared two weeks in advance. We welcome applications from everyone. Apply by 15 November.\"\n\nSelin read it. \"Better. It talks to Nermin. And to Ece.\"\n\nLeyla thought about the old ad. How many good drivers had already closed it, and she had never known?","vocab":[{"word":"over her shoulder","en":"From behind her, looking at her screen.","tr":"omzunun üstünden","fa":"از پشت سرش، با نگاه به صفحه‌اش"},{"word":"fleet","en":"A group of vehicles owned by a company.","tr":"araç filosu","fa":"ناوگان (خودروهای یک شرکت)"},{"word":"schedule","en":"A plan of when you work.","tr":"çalışma programı","fa":"برنامه‌ی کاری"},{"word":"in advance","en":"Before something happens.","tr":"önceden","fa":"از قبل"},{"word":"welcome","en":"To be glad to receive.","tr":"memnuniyetle karşılamak","fa":"از چیزی استقبال کردن"}],"quiz":[{"prompt":"What was wrong with the first ad?","options":["It excluded some people by age and gender","It was too short","It had no company name"],"correct":0},{"prompt":"Choose the correct sentence.","options":["We need drivers who enjoy road work.","We need drivers what enjoy road work.","We need drivers whose enjoy road work."],"correct":0},{"prompt":"Why did Leyla read the ad \"as someone else\"?","options":["To see how different readers would feel","To practise her English","To save time"],"correct":0},{"prompt":"How did Leyla feel at the end?","options":["Uneasy about the good drivers she may have lost","Proud of the first ad","Angry at Selin"],"correct":0}],"notice":{"en":"Selin asks Leyla to read her ad 'as someone else'. Watch who she becomes, and which words push them away.","tr":"Selin, Leyla'dan ilanı 'başka biri gibi' okumasını istiyor. Kimin yerine geçtiğine ve hangi kelimelerin onları uzaklaştırdığına dikkat et.","fa":"سلین از لیلا می‌خواهد آگهی را «از نگاه کس دیگری» بخواند. دقت کن لیلا جای چه کسانی می‌رود و کدام کلمه‌ها آن‌ها را دور می‌کند."},"bridge":{"en":"Leyla's new ad talks to 'you' and uses 'who'. Next: see how a reader-friendly ad works.","tr":"Leyla'nın yeni ilanı 'you' diye sesleniyor ve 'who' kullanıyor. Sırada: okura dönük bir ilanın nasıl çalıştığını gör.","fa":"آگهی تازه‌ی لیلا با «you» حرف می‌زند و از «who» استفاده می‌کند. قدم بعد: ببین آگهیِ خواننده‌محور چطور کار می‌کند."}},"speaking":{"id":"hr-2-2","course":"hr","unit":"hr-2-2","rounds":[60,30],"topic":{"en":"Explaining an Inclusive Job Ad to a Manager","tr":"Bir Yöneticiye Kapsayıcı İlanı Açıklamak","fa":"توضیح دادن آگهی فراگیر به مدیر"},"warmup":{"en":"Have you ever not applied for a job because of one line in the ad? What was it?","tr":"Hiç ilandaki tek bir satır yüzünden bir işe başvurmadığın oldu mu? Neydi?","fa":"تا حالا پیش آمده که فقط به خاطر یک جمله در آگهی، برای کاری درخواست ندهی؟ آن جمله چه بود؟"},"questions":[{"en":"Tell Omar why \"young and energetic\" should change. Give one reason.","tr":"Omar'a \"young and energetic\" ifadesinin neden değişmesi gerektiğini söyle. Bir sebep ver.","fa":"به عمر توضیح بده چرا عبارت «young and energetic» باید عوض شود. یک دلیل بیاور."},{"en":"Offer a better line that says what the driver does instead.","tr":"Bunun yerine sürücünün ne yaptığını söyleyen daha iyi bir cümle öner.","fa":"یک جمله‌ی بهتر پیشنهاد کن که به‌جایش بگوید راننده چه کار می‌کند."},{"en":"Answer Omar: \"Isn't this just more work for us?\"","tr":"Omar'a cevap ver: \"Bu bize sadece fazladan iş değil mi?\"","fa":"عمر می‌پرسد: «⁨Isn't this just more work for us?⁩» به او جواب بده."}],"followups":[{"en":"Say your answer in 60 seconds, then in 30.","tr":"Cevabını 60, sonra 30 saniyede söyle.","fa":"جوابت را یک بار در ۶۰ ثانیه و بعد در ۳۰ ثانیه بگو."},{"en":"Now read one line from a real job ad. Who might it put off? Say a fairer version.","tr":"Şimdi gerçek bir iş ilanından bir satır oku. Kimi uzaklaştırabilir? Daha adil hâlini söyle.","fa":"حالا یک خط از یک آگهی شغلی واقعی را بخوان. چه کسی را پس می‌زند؟ نسخه‌ی منصفانه‌ترش را بگو."}],"expressions":[{"phrase":"It may exclude some good applicants.","meaning":{"en":"Gives a reason without blaming.","tr":"Suçlamadan sebep verir.","fa":"دلیل می‌آورد، بدون اینکه کسی را مقصر کند."}},{"phrase":"What if we say it like this?","meaning":{"en":"Offers an alternative politely.","tr":"Kibarca alternatif sunar.","fa":"مؤدبانه یک راه دیگر پیشنهاد می‌کند."}},{"phrase":"It gives us a bigger pool of candidates.","meaning":{"en":"Shows the business benefit.","tr":"İş yararını gösterir.","fa":"سودش را برای کسب‌وکار نشان می‌دهد."}}],"culture":{"en":"In the UK and EU, age and gender wording in job ads can break equality laws. UAE labour law also bans discrimination in hiring on grounds such as sex, religion and national origin. Even where it is legal, inclusive wording usually brings more good applicants. Under the EU Pay Transparency Directive, which countries had to make law by June 2026 (many are late), employers must also tell applicants the pay or pay range before the interview, and may not ask about their past pay. Check the local law with a lawyer for real ads.","tr":"Birleşik Krallık ve AB'de iş ilanlarındaki yaş ve cinsiyet ifadeleri eşitlik yasalarını çiğneyebilir. BAE iş kanunu da işe alımda cinsiyet, din ve ulusal köken gibi nedenlerle ayrımcılığı yasaklar. Yasal olsa bile kapsayıcı ifade genellikle daha çok nitelikli aday getirir. Ülkelerin Haziran 2026’ya kadar yasalaştırması gereken AB Ücret Şeffaflığı Direktifi’ne göre (birçok ülke gecikti) işverenler, adaylara mülakattan önce maaşı ya da maaş aralığını söylemek zorundadır ve adayların geçmiş maaşlarını soramaz. Gerçek ilanlar için yerel yasayı bir avukatla kontrol et.","fa":"در بریتانیا و اتحادیه‌ی اروپا، عبارت‌هایی درباره‌ی سن و جنسیت در آگهی استخدام ممکن است قوانین منع تبعیض را نقض کند. قانون کار امارات هم تبعیض در استخدام را به دلایلی مثل جنسیت، دین و ملیت ممنوع کرده است. حتی جایی که قانوناً اشکالی ندارد، آگهی فراگیر معمولاً متقاضیان خوب بیشتری جذب می‌کند. اتحادیه‌ی اروپا هم دستورالعملی برای شفافیت حقوق دارد که کشورها باید تا ژوئن ۲۰۲۶ آن را وارد قانون خود می‌کردند (خیلی از کشورها هنوز عقب‌اند). طبق آن، کارفرماها باید پیش از مصاحبه حقوق یا بازه‌ی حقوق را به متقاضی بگویند و اجازه ندارند حقوق قبلی او را بپرسند. برای آگهی واقعی، قانون محلی را با یک مشاور حقوقی بررسی کن."},"model":"Omar, I'd like to change the first line of the ad. Words about age and strength may exclude some good applicants, for example an experienced driver of fifty. What if we say it like this: You will drive a fixed route, three or four nights a week, and lift boxes up to twenty kilos? It says what the job is, and it gives us a bigger pool of candidates.","selfCheck":[{"en":"I gave one clear reason for the change.","tr":"Değişiklik için net bir neden verdim.","fa":"برای تغییر یک دلیل روشن گفتم."},{"en":"I offered a better line that says what the driver does.","tr":"Sürücünün ne yaptığını söyleyen daha iyi bir cümle önerdim.","fa":"جمله‌ی بهتری پیشنهاد کردم که می‌گوید راننده چه کاری می‌کند."},{"en":"I used 'What if we say it like this?' or a similar soft opener.","tr":"'What if we say it like this?' ya da benzer yumuşak bir giriş kullandım.","fa":"از «⁨What if we say it like this?⁩» یا یک شروع نرم مشابه استفاده کردم."},{"en":"The last round fitted in the time.","tr":"Son tur süreye sığdı.","fa":"دور آخر در زمانش تمام شد."}]},"judge":{"id":"c-hr-2-2-j","course":"hr","unit":"hr-2-2","type":"judge","parts":["Age","Gender","Nationality"],"instruction":{"en":"Tap the kinds of bias you can find in each line. Some lines have none.","tr":"Her satırda bulduğun önyargı türlerine dokun. Bazı satırlarda hiç yok.","fa":"در هر خط، نوع سوگیری‌هایی را که می‌بینی لمس کن. بعضی خط‌ها هیچ سوگیری‌ای ندارند."},"items":[{"answer":"We are a young, energetic team.","present":["Age"],"fix":{"en":"\"Young\" points to age. Say what the team does: \"We are a fast-moving team.\"","tr":"\"Young\" yaşa işaret eder. Ekibin ne yaptığını söyle: \"We are a fast-moving team.\"","fa":"young به سن اشاره دارد. بگو تیم چه کاری می‌کند: «⁨We are a fast-moving team.⁩»"}},{"answer":"We need strong men who can drive at night.","present":["Gender"],"fix":{"en":"\"Men\" excludes women. Say: \"You will drive at night and lift boxes up to 20 kg.\"","tr":"\"Men\" kadınları dışlar. Şöyle yaz: \"You will drive at night and lift boxes up to 20 kg.\"","fa":"men زنان را از دایره بیرون می‌گذارد. بنویس: «⁨You will drive at night and lift boxes up to 20 kg.⁩»"}},{"answer":"Applicants must be native English speakers.","present":["Nationality"],"fix":{"en":"\"Native\" excludes fluent speakers from other countries. Say: \"Fluent spoken and written English.\"","tr":"\"Native\" başka ülkelerden akıcı konuşanları dışlar. Şöyle yaz: \"Fluent spoken and written English.\"","fa":"native کسانی را که اهل کشورهای دیگرند ولی روان صحبت می‌کنند کنار می‌گذارد. بنویس: «⁨Fluent spoken and written English.⁩»"}},{"answer":"You will drive three or four nights a week and receive your schedule two weeks in advance.","present":[],"fix":null},{"answer":"Ideal candidate: a young salesman with a Turkish passport.","present":["Age","Gender","Nationality"],"fix":{"en":"All three: age (\"young\"), gender (\"salesman\") and nationality (\"Turkish passport\"). Say: \"sales representative with the right to work in the UAE.\"","tr":"Üçü de var: yaş (\"young\"), cinsiyet (\"salesman\") ve uyruk (\"Turkish passport\"). Şöyle yaz: \"sales representative with the right to work in the UAE.\"","fa":"هر سه نوع سوگیری در این خط هست: سن (young)، جنسیت (salesman) و ملیت (Turkish passport). بنویس: «⁨sales representative with the right to work in the UAE.⁩»"}}]},"writing":{"id":"c-hr-2-2-w","title":{"en":"The job ad for Dubai drivers","tr":"Dubai sürücüleri için iş ilanı","fa":"آگهی استخدام راننده برای دبی"},"course":"hr","unit":"hr-2-2","type":"writing","difficulty":"medium","prompt":{"en":"Write the job ad for Delivery Driver, Dubai (70-90 words): a welcoming opening, what you will do, the pay range, 2 benefits, a closing date, one inclusion sentence and one line offering adjustments. Check it with the bias list.","tr":"Delivery Driver, Dubai için iş ilanını yaz (70-90 kelime): karşılayıcı bir giriş, ne yapacağın, maaş aralığı, 2 yan hak, son başvuru tarihi, bir kapsayıcılık cümlesi ve makul düzenleme teklif eden bir cümle. Önyargı listesiyle kontrol et.","fa":"آگهی استخدام شغل «Delivery Driver, Dubai» را بنویس (۷۰ تا ۹۰ کلمه): یک شروع گرم و خوشامدگو، کارهایی که فرد انجام خواهد داد، بازه‌ی حقوق، دو مزیت، آخرین مهلت درخواست، یک جمله که نشان دهد همه می‌توانند درخواست بدهند و یک جمله که بگوید در صورت نیاز، تسهیلات لازم فراهم می‌شود. در آخر، متن را با فهرست سوگیری‌ها چک کن."},"model":"Join our growing team in Dubai. We are looking for drivers who enjoy road work and take pride in on-time delivery. You will drive on a fixed route, three or four nights a week, and you will receive your schedule two weeks in advance. We offer 7,000 to 9,000 dirhams a month, a travel allowance and family health insurance. We welcome applications from everyone. If you need any adjustments to apply or to attend an interview, just tell us. Apply by 15 November.","frame":"Join our ___ team in ___. We are looking for ___ who ___. You will ___. We offer ___ a month, ___ and ___. We welcome applications from ___. If you need any adjustments to apply or to attend an interview, ___. Apply by ___.","words":[{"word":"apply"},{"word":"benefits"},{"word":"welcome"}],"minWords":60,"minSentences":5,"rubric":["Task done: opening, duties, pay range, 2 benefits, closing date, inclusion and adjustments lines","Organised: attractive order, short sentences","Language: you + imperatives; who; no -ing after imperative and","Tone: welcoming, no age, gender or origin cues"],"rubricI18n":{"tr":["Görev: giriş, görevler, maaş aralığı, 2 yan hak, son başvuru tarihi, kapsayıcılık ve düzenleme cümleleri","Düzen: çekici bir sıra, kısa cümleler","Dil: you + emir kipi; who; emirden sonra gelen and'in ardından -ing yok","Üslup: davetkâr; yaş, cinsiyet ya da köken ipucu yok"],"fa":["کامل بودن کار: شروع، وظایف، بازه‌ی حقوق، دو مزیت، آخرین مهلت، جمله‌ی فراگیر و جمله‌ی تسهیلات","نظم: ترتیبی جذاب، جمله‌های کوتاه","زبان: you و فعل امری؛ who؛ بعد از and که پس از فعل امری می‌آید، ‎-ing نیاید","لحن: خوشامدگو؛ بدون اشاره به سن، جنسیت یا ملیت"]},"portfolio":"hr-final-1","parts":[{"t":{"en":"A welcoming opening","tr":"Davet eden bir açılış","fa":"شروعی که دعوت می‌کند"},"find":["join our","we are looking for"],"sample":"Join our growing team in Dubai"},{"t":{"en":"What you will do","tr":"Ne yapacağın","fa":"کاری که انجام می‌دهی"},"find":["you will"],"sample":"a fixed route, three or four nights a week"},{"t":{"en":"The pay range and two benefits","tr":"Maaş aralığı ve iki yan hak","fa":"بازه‌ی حقوق و دو مزیت"},"find":["we offer","dirhams","allowance","insurance"],"sample":"7,000-9,000 dirhams; travel allowance; health insurance"},{"t":{"en":"An inclusion line and an offer of adjustments","tr":"Kapsayıcı bir cümle ve düzenleme teklifi","fa":"یک جمله‌ی فراگیر و پیشنهاد تسهیلات"},"find":["we welcome","adjustments","everyone"],"sample":"we welcome everyone; tell us about any adjustments"},{"t":{"en":"A closing date","tr":"Son başvuru tarihi","fa":"آخرین مهلت درخواست"},"find":["apply by","closing date"],"sample":"apply by 15 November"}]},"perspective":{"id":"c-hr-2-2-p","title":{"en":"Nermin and Ece read your ad","tr":"Nermin ve Ece ilanını okuyor","fa":"نرمین و اجه آگهی‌ات را می‌خوانند"},"course":"hr","unit":"hr-2-2","type":"perspective","minSentences":2,"prompt":{"en":"Read your ad twice: first as Nermin, 52, then as Ece, a working mother. Write 1-2 sentences for each in first person: do you apply, and why?","tr":"İlanını iki kez oku: önce 52 yaşındaki Nermin, sonra çalışan bir anne olan Ece olarak. Her biri için birinci tekil şahısla 1-2 cümle yaz: başvuruyor musun ve neden?","fa":"آگهی‌ات را دو بار بخوان: یک بار از چشم نرمین، ۵۲ ساله، و یک بار از چشم اجه، مادری شاغل. برای هر کدام از زبان خودش یکی دو جمله بنویس: درخواست می‌دهد یا نه، و چرا؟"}},"exit":{"id":"c-hr-2-2-x","course":"hr","unit":"hr-2-2","type":"exit","items":[{"from":"hr-2-2","kind":"blank","prompt":"Apply today and ___ your career with us.","options":["to start","start","starting"],"correct":1,"point":2,"why":{"en":"start: after 'and', the second imperative is plain too: apply ... and start. 'To start' and 'starting' break the pair.","tr":"start: 'and'den sonra ikinci emir de yalın olur: apply ... and start. 'To start' ve 'starting' çifti bozar.","fa":"start درست است، چون بعد از and فعل امری دوم هم ساده است: apply ... and start. to start و starting این جفت را خراب می‌کنند."}},{"from":"hr-2-2","kind":"blank","prompt":"We want people ___ like working with customers.","options":["who","which","whose"],"correct":0,"point":2,"why":{"en":"who: it refers to people. 'Which' is for things, and 'whose' shows ownership.","tr":"who: insanları anlatır. 'Which' şeyler içindir; 'whose' sahiplik gösterir.","fa":"who درست است، چون به آدم‌ها برمی‌گردد. which برای چیزهاست و whose مالکیت را نشان می‌دهد."},"hint2":{"en":"The gap joins people to what they do. Which word starts a clause about people?","tr":"Boşluk insanları yaptıkları şeye bağlıyor. İnsanlarla ilgili bir yan cümleyi hangi kelime başlatır?","fa":"جای خالی آدم‌ها را به کاری که می‌کنند وصل می‌کند. کدام کلمه جمله‌ای درباره‌ی آدم‌ها را شروع می‌کند؟"}},{"from":"hr-2-2","kind":"mcq","prompt":"Which wording is free of bias?","options":["Fluent English (spoken and written)","Young, native English speaker","Strong man wanted"],"correct":0,"point":1,"why":{"en":"'Fluent English (spoken and written)' describes the job's need. 'Young, native speaker' and 'strong man' exclude people by age, origin or sex.","tr":"'Fluent English (spoken and written)' işin ihtiyacını anlatır. 'Young, native speaker' ve 'strong man' insanları yaş, köken ya da cinsiyete göre dışlar.","fa":"«Fluent English (spoken and written)» نیاز خود کار را می‌گوید. «Young, native speaker» و «Strong man» آدم‌ها را بر اساس سن، ملیت یا جنسیت کنار می‌گذارند."}},{"from":"hr-2-1","kind":"blank","prompt":"Night drivers ___ be over 21.","options":["must to","must","must be hold"],"correct":1,"point":2,"why":{"en":"must: must + plain verb. 'Must to' is not English, and 'must be hold' mixes two forms.","tr":"must: must + yalın fiil. 'Must to' İngilizce değildir; 'must be hold' iki yapıyı karıştırır.","fa":"must درست است: must و فعل ساده. must to انگلیسی نیست و must be hold دو ساختار را قاطی می‌کند."},"hint2":{"en":"This is an essential requirement. Which modal makes a requirement, and does it take to after it?","tr":"Bu zorunlu bir şart. Hangi modal fiil şart bildirir ve ondan sonra to gelir mi?","fa":"این یک شرط ضروری است. کدام فعل کمکی شرط را می‌رساند و بعدش ⁨to⁩ می‌آید؟"}},{"from":"hr-1-4","kind":"blank","prompt":"Have you ever ___ to Dubai?","options":["been","be","being"],"correct":0,"point":2,"why":{"en":"been: 'Have you ever been to' + a place. 'Be' and 'being' are not past participles.","tr":"been: 'Have you ever been to' + yer. 'Be' ve 'being' üçüncü hâl değildir.","fa":"been درست است، چون Have you ever been to و بعد اسم مکان. be و being اسم مفعول نیستند."}},{"from":"hr-1-2","kind":"mcq","prompt":"Which is a polite request?","options":["Could you confirm the date?","Confirm the date now.","You confirm date."],"correct":0,"point":2,"why":{"en":"'Could you confirm the date?' asks politely. 'Confirm the date now' is an order, and 'You confirm date' is broken English.","tr":"'Could you confirm the date?' kibarca sorar. 'Confirm the date now' bir emirdir; 'You confirm date' bozuk İngilizcedir.","fa":"«Could you confirm the date?» مؤدبانه می‌پرسد. «Confirm the date now» دستور است و «You confirm date» انگلیسی شکسته است."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
